    private static function add(array &$tests,int &$passed,int &$failed,int &$warnings,string $type,string $name,string $expected,string $actual,string $status,array $evidence):void{$tests[]=['type'=>$type,'name'=>$name,'expected'=>$expected,'actual'=>$actual,'status'=>$status,'evidence'=>$evidence];match($status){'passed'=>$passed++,'failed'=>$failed++,default=>$warnings++};}
