        if(!$links){self::add($tests,$passed,$failed,$warnings,'links','فحص الروابط الداخلية','وجود روابط داخلية','لم يتم العثور على روابط ثابتة','warning',[]);return;}foreach(array_keys($links) as $path){try{$r=HttpClient::head('https://'.$domain.$path,10);$status=(int)$r['status'];if(in_array($status,[405,501],true)){$r=HttpClient::probe('https://'.$domain.$path,10,32768);$status=(int)$r['status'];}$ok=$status>=200&&$status<400;self::add($tests,$passed,$failed,$warnings,'link','رابط داخلي '.$path,'رد ناجح أو تحويل سليم','حالة الرد '.$status,$ok?'passed':'failed',['final_url'=>$r['final_url']??('https://'.$domain.$path)]);}catch(Throwable $e){self::add($tests,$passed,$failed,$warnings,'link','رابط داخلي '.$path,'يمكن الوصول له',AdminUi::humanError($e->getMessage()),'failed',[]);}}
    }
